  const match = /^\$?(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d+))?$/.exec(input);
  if (match === null) {
    throw new TypeError("invalid money amount");
  }
  const dollars = Number(match[1].replace(/,/g, ""));
  const cents = match[2] ?? "";
  let totalCents = dollars * 100;
  if (cents.length > 0) {
    totalCents += Number(cents.slice(0, 2));
    if (cents.length > 2 && Number(cents[2]) >= 5) {
      totalCents += 1;
    }
  }
  return totalCents / 100;
