  const match = /^\$?(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d+))?$/.exec(input);
  if (!match) {
    throw new TypeError("invalid money amount");
  }
  const whole = match[1].replace(/,/g, "");
  let cents = (match[2] ?? "").padEnd(2, "0");
  let totalCents = Number(whole) * 100 + Number(cents.slice(0, 2));
  if ((match[2]?.length ?? 0) > 2 && (match[2] ?? "")[2] >= "5") {
    totalCents += 1;
  }
  return totalCents / 100;
