  if (!match) {
    throw new TypeError("invalid money amount");
  }
  const dollars = Number(match[1]!.replace(/,/g, ""));
  const centsStr = match[2] ?? "";
  let cents = Number((centsStr + "00").slice(0, 2));
  if (centsStr.length > 2) {
    const third = Number(centsStr[2]);
    if (third >= 5) {
      cents += 1;
    }
  }
  const result = (dollars * 100 + cents) / 100;
  if (!Number.isFinite(result)) {
    throw new TypeError("invalid money amount");
  }
  return result;
